mapper.select:
SELECT entry_id, entry_name, display_name, description, author, version, transport_type, endpoint_url, command, args, source_platform, dns_verified, entry_status, rating, use_count, tags, icon_url, homepage_url FROM km_mcp_registry_entry WHERE entry_status = 'active'
AND to_tsvector('simple', coalesce(entry_name, '') || ' ' || coalesce(display_name, '') || ' ' || coalesce(description, '')) @@ plainto_tsquery('simple', #{keyword})
AND source_platform = #{sourcePlatform}
AND transport_type = #{transportType}
AND tags @> #{tags}::jsonb
ORDER BY
ts_rank(to_tsvector('simple', coalesce(entry_name, '') || ' ' || coalesce(display_name, '') || ' ' || coalesce(description, '')), plainto_tsquery('simple', #{keyword})) DESC,
entry_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM km_mcp_registry_entry WHERE entry_status = 'active'
AND to_tsvector('simple', coalesce(entry_name, '') || ' ' || coalesce(display_name, '') || ' ' || coalesce(description, '')) @@ plainto_tsquery('simple', #{keyword})
AND source_platform = #{sourcePlatform}
AND transport_type = #{transportType}
AND tags @> #{tags}::jsonb

